B.MR={"Python Variables":0,"Python Data Types":1,"Python Input and Output":2,"Python Operators":3,"Python Conditional Statements":4,"Python Loops":5,"Python Functions":6}
B.MX={"Variables 1: Student Introduction":0,"Variables 2: School Bag Items":1,"Variables 3: Marks Update":2}
B.LL=new A.bs(B.MX,['# A variable stores a value so we can use it later.\n# Here we save three pieces of information about one student.\nstudent_name = "Aarav"\nstudent_class = 6\nfavorite_subject = "Science"\n\n# print() shows the value stored inside each variable.\nprint("Student name:", student_name)\nprint("Class:", student_class)\nprint("Favorite subject:", favorite_subject)\n','# Variables can change while the program runs.\n# We start with 4 notebooks and 1 water bottle.\nnotebooks = 4\nwater_bottle = 1\n\n# Add 2 more notebooks to the old value.\nnotebooks = notebooks + 2\n\n# Display the updated values.\nprint("Notebooks now:", notebooks)\nprint("Water bottles:", water_bottle)\n','# Store the first marks value in a variable.\nmath_marks = 72\nprint("Old math marks:", math_marks)\n\n# Replace the old value with a new one.\nmath_marks = 85\nprint("Updated math marks:", math_marks)\n'],t.l)
B.MV={"Data Types 1: Basic Types":0,"Data Types 2: List of Subjects":1,"Data Types 3: Student Record":2}
B.LO=new A.bs(B.MV,['# A string stores text.\nstudent_name = "Meera"\n# An integer stores whole numbers.\nage = 12\n# A float stores decimal numbers.\nheight = 4.8\n# A boolean stores True or False.\nlikes_python = True\n\n# type() tells us the data type of each value.\nprint(student_name, "->", type(student_name))\nprint(age, "->", type(age))\nprint(height, "->", type(height))\nprint(likes_python, "->", type(likes_python))\n','# A list stores many items in one variable.\nsubjects = ["English", "Math", "Science", "Computer"]\n\n# Print the full list.\nprint("Subjects:", subjects)\n# Index 0 means the first item in the list.\nprint("First subject:", subjects[0])\n# len() tells us how many items are inside the list.\nprint("How many subjects?", len(subjects))\n','# A dictionary stores information as key-value pairs.\nstudent = {\n    "name": "Riya",\n    "class": 7,\n    "house": "Blue"\n}\n\n# Print the whole dictionary.\nprint("Student record:", student)\n# Use keys like "name" and "house" to get specific values.\nprint("Name:", student["name"])\nprint("House:", student["house"])\n'],t.l)
B.MO={"Input Output 1: Friendly Greeting":0,"Input Output 2: Age Next Year":1,"Input Output 3: Two Numbers":2}
B.M3=new A.bs(B.MO,['# input() asks the user to type something.\nname = input("What is your name? ")\n\n# print() shows the typed answer on the screen.\nprint("Hello,", name)\nprint("Welcome to Python class!")\n','# input() gives text, so int() changes it into a whole number.\nage = int(input("Enter your age: "))\n\n# Add 1 to find the age for next year.\nnext_year_age = age + 1\n\nprint("Your age next year will be", next_year_age)\n','# Ask the user for two numbers.\nfirst_number = int(input("Enter first number: "))\nsecond_number = int(input("Enter second number: "))\n\n# Add them and store the answer.\ntotal = first_number + second_number\nprint("The sum is", total)\n'],t.l)
B.MM={"Operators 1: Arithmetic Practice":0,"Operators 2: Comparison Check":1,"Operators 3: Logical Decisions":2}
B.LY=new A.bs(B.MM,['# Save two numbers for practice.\nnumber1 = 18\nnumber2 = 6\n\n# Use arithmetic operators to calculate answers.\nprint("Addition:", number1 + number2)\nprint("Subtraction:", number1 - number2)\nprint("Multiplication:", number1 * number2)\nprint("Division:", number1 / number2)\n','# Comparison operators check relationships between values.\nenglish = 78\nscience = 78\n\n# Each comparison gives a boolean result: True or False.\nprint("English > Science:", english > science)\nprint("English < Science:", english < science)\nprint("English == Science:", english == science)\n','# Logical operators combine boolean values.\nfinished_homework = True\nbrought_book = True\n\n# and is True only when both conditions are True.\nprint("Can join activity:", finished_homework and brought_book)\n# Here one condition is False, so the result becomes False.\nprint("Missed one requirement:", finished_homework and False)\n# or is True if at least one condition is True.\nprint("At least one is ready:", finished_homework or False)\n'],t.l)
B.MI={"Conditionals 1: Voting Style Check":0,"Conditionals 2: Pass or Improve":1,"Conditionals 3: School Uniform Advice":2}
B.Mb=new A.bs(B.MI,['# The program checks a condition and chooses a path.\nage = 14\n\n# If age is 18 or more, run the first block.\nif age >= 18:\n    print("You are an adult.")\n# Otherwise, run the else block.\nelse:\n    print("You are not an adult yet.")\n','# elif lets us check another condition if the first one is False.\nmarks = 67\n\nif marks >= 90:\n    print("Excellent work!")\nelif marks >= 50:\n    print("You passed the test.")\nelse:\n    print("Keep practicing and try again.")\n','# Booleans are useful in conditions.\nis_raining = True\n\n# If it is raining, give one message.\nif is_raining:\n    print("Take an umbrella to school.")\n# If not, give a different message.\nelse:\n    print("Enjoy the sunny day.")\n'],t.l)
B.MP={"Loops 1: Counting Numbers":0,"Loops 2: Revision with While":1,"Loops 3: Print Each Fruit":2}
B.Ma=new A.bs(B.MP,['# range(1, 6) gives numbers from 1 up to 5.\n# The loop runs once for each number.\nfor number in range(1, 6):\n    print("Count:", number)\n','# A while loop repeats while the condition stays True.\nchapter = 1\n\nwhile chapter <= 3:\n    print("Revise chapter", chapter)\n    # Increase the chapter number so the loop can move forward.\n    chapter = chapter + 1\n','# This list has four fruit names.\nfruits = ["apple", "banana", "mango", "orange"]\n\n# The loop takes one fruit at a time from the list.\nfor fruit in fruits:\n    print("I like", fruit)\n'],t.l)
B.ML={"Functions 1: Simple Greeting Function":0,"Functions 2: Add Two Numbers":1,"Functions 3: Return a Result":2}
B.M4=new A.bs(B.ML,['# A function is a named block of code.\ndef greet_student():\n    # These lines run only when the function is called.\n    print("Hello student!")\n    print("Let us learn Python today.")\n\n# Call the function to use it.\ngreet_student()\n','# This function takes two inputs called parameters.\ndef add_numbers(a, b):\n    # Add the two parameters and store the result.\n    answer = a + b\n    print("Sum is", answer)\n\n# Call the function with different values.\nadd_numbers(5, 8)\nadd_numbers(12, 3)\n','# return sends a value back from the function.\ndef square(number):\n    return number * number\n\n# Store the returned value in a variable.\nresult = square(7)\nprint("Square is", result)\n'],t.l)
B.hA=new A.bs(B.MR,[B.LL,B.LO,B.M3,B.LY,B.Mb,B.Ma,B.M4],A.aq("bs<m,aF<m,m>>"))
